/**
 * JSZip Compatible Lightweight Implementation for RenderX Image Studio
 * Supports new JSZip(), zip.file(name, data), and zip.generateAsync({ type: 'blob' })
 */
(function (global) {
  'use strict';

  // Precomputed CRC-32 table
  const crcTable = (() => {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      table[i] = c >>> 0;
    }
    return table;
  })();

  function crc32(bytes) {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < bytes.length; i++) {
      crc = (crc >>> 8) ^ crcTable[(crc ^ bytes[i]) & 0xFF];
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  class JSZip {
    constructor() {
      this.files = new Map();
    }

    /**
     * Add a file to the ZIP
     * @param {string} filename 
     * @param {string|ArrayBuffer|Uint8Array|Blob} data 
     * @param {Object} [options]
     */
    file(filename, data, options = {}) {
      if (!data) return this;
      this.files.set(filename, { data, options });
      return this;
    }

    /**
     * Generate the ZIP archive as a Blob or ArrayBuffer
     * @param {Object} options 
     * @returns {Promise<Blob|ArrayBuffer>}
     */
    async generateAsync(options = { type: 'blob' }) {
      const processedFiles = [];
      const encoder = new TextEncoder();

      for (const [name, fileEntry] of this.files.entries()) {
        let rawData = fileEntry.data;
        let bytes;

        if (rawData instanceof Blob) {
          const ab = await rawData.arrayBuffer();
          bytes = new Uint8Array(ab);
        } else if (rawData instanceof ArrayBuffer) {
          bytes = new Uint8Array(rawData);
        } else if (rawData instanceof Uint8Array) {
          bytes = rawData;
        } else if (typeof rawData === 'string') {
          if (rawData.startsWith('data:') && rawData.includes(';base64,')) {
            const b64 = rawData.split(';base64,')[1];
            const bin = atob(b64);
            bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
          } else {
            bytes = encoder.encode(rawData);
          }
        } else {
          bytes = new Uint8Array(0);
        }

        const nameBytes = encoder.encode(name);
        const checksum = crc32(bytes);

        processedFiles.push({
          name,
          nameBytes,
          bytes,
          crc: checksum,
          size: bytes.length
        });
      }

      let localHeaderTotal = 0;
      let centralDirTotal = 0;

      for (const f of processedFiles) {
        localHeaderTotal += 30 + f.nameBytes.length + f.size;
        centralDirTotal += 46 + f.nameBytes.length;
      }

      const totalSize = localHeaderTotal + centralDirTotal + 22;
      const buffer = new ArrayBuffer(totalSize);
      const view = new DataView(buffer);
      const outBytes = new Uint8Array(buffer);

      let offset = 0;
      const centralEntries = [];

      for (const f of processedFiles) {
        const localOffset = offset;
        centralEntries.push({ f, localOffset });

        view.setUint32(offset, 0x04034b50, true);
        view.setUint16(offset + 4, 10, true);
        view.setUint16(offset + 6, 0x0800, true);
        view.setUint16(offset + 8, 0, true);
        view.setUint16(offset + 10, 0, true);
        view.setUint16(offset + 12, 0, true);
        view.setUint32(offset + 14, f.crc, true);
        view.setUint32(offset + 18, f.size, true);
        view.setUint32(offset + 22, f.size, true);
        view.setUint16(offset + 26, f.nameBytes.length, true);
        view.setUint16(offset + 28, 0, true);

        offset += 30;
        outBytes.set(f.nameBytes, offset);
        offset += f.nameBytes.length;
        outBytes.set(f.bytes, offset);
        offset += f.size;
      }

      const centralDirOffset = offset;
      for (const entry of centralEntries) {
        const f = entry.f;

        view.setUint32(offset, 0x02014b50, true);
        view.setUint16(offset + 4, 20, true);
        view.setUint16(offset + 6, 10, true);
        view.setUint16(offset + 8, 0x0800, true);
        view.setUint16(offset + 10, 0, true);
        view.setUint16(offset + 12, 0, true);
        view.setUint16(offset + 14, 0, true);
        view.setUint32(offset + 16, f.crc, true);
        view.setUint32(offset + 20, f.size, true);
        view.setUint32(offset + 24, f.size, true);
        view.setUint16(offset + 28, f.nameBytes.length, true);
        view.setUint16(offset + 30, 0, true);
        view.setUint16(offset + 32, 0, true);
        view.setUint16(offset + 34, 0, true);
        view.setUint16(offset + 36, 0, true);
        view.setUint32(offset + 38, 0, true);
        view.setUint32(offset + 42, entry.localOffset, true);

        offset += 46;
        outBytes.set(f.nameBytes, offset);
        offset += f.nameBytes.length;
      }

      const centralDirLength = offset - centralDirOffset;

      view.setUint32(offset, 0x06054b50, true);
      view.setUint16(offset + 4, 0, true);
      view.setUint16(offset + 6, 0, true);
      view.setUint16(offset + 8, processedFiles.length, true);
      view.setUint16(offset + 10, processedFiles.length, true);
      view.setUint32(offset + 12, centralDirLength, true);
      view.setUint32(offset + 16, centralDirOffset, true);
      view.setUint16(offset + 20, 0, true);

      const outType = options.type || 'blob';
      if (outType === 'arraybuffer') {
        return buffer;
      } else if (outType === 'uint8array') {
        return outBytes;
      }

      return new Blob([buffer], { type: 'application/zip' });
    }
  }

  global.JSZip = JSZip;
})(typeof window !== 'undefined' ? window : globalThis);
